def _():
    ui.update_slider("min_pop", value=0)
    ui.update_select("city", selected="Auckland")
Call ui.update_* from inside a reactive.effect. Shiny takes care of pushing the change to the browser.

A small worked example
Here is the suburbs explorer from 3.2, rewritten with a sidebar layout, a navset, cards, and a theme. The logic is identical; only the UI changed.
from shiny import App, ui, render, reactive
from shiny.render import DataGrid
import shinyswatch
import pandas as pd
import matplotlib.pyplot as plt

data = pd.DataFrame({
    "city": ["Auckland"] * 5 + ["Wellington"] * 4,
    "suburb": ["Ponsonby", "Parnell", "Mt Eden", "Newmarket", "Grey Lynn",
               "Kelburn", "Newtown", "Karori", "Thorndon"],
    "population": [12500, 8900, 15300, 11200, 14800, 4500, 9800, 15200, 3100],
    "median_income": [75000, 95000, 68000, 82000, 71000, 62000, 58000, 78000, 88000],
})

app_ui = ui.page_sidebar(
    ui.sidebar(
        ui.input_select("city", "City", choices=sorted(data["city"].unique())),
        ui.input_slider("min_pop", "Minimum population", 0, 20000, 0, step=1000),
        ui.input_action_button("reset", "Reset filters"),
    ),
    ui.navset_tab(
        ui.nav_panel("Summary",
            ui.card(
                ui.card_header("Results"),
                ui.output_text("summary"),
            ),
        ),
        ui.nav_panel("Chart",
            ui.card(
                ui.card_header("Median income by suburb"),
                ui.output_plot("chart"),
            ),
        ),
        ui.nav_panel("Data",
            ui.output_data_frame("grid"),
        ),
    ),
    title="Suburbs explorer",
    theme=shinyswatch.theme.flatly,
)

def server(input, output, session):

    @reactive.calc
    def filtered():
        df = data[data["city"] == input.city()]
        return df[df["population"] &gt;= input.min_pop()]

    @render.text
    def summary():
        df = filtered()
        return f"{len(df)} suburbs, mean income ${df['median_income'].mean():,.0f}"

    @render.plot
    def chart():
        df = filtered()
        fig, ax = plt.subplots(figsize=(7, 4))
        ax.barh(df["suburb"], df["median_income"], color="steelblue")
        ax.set_xlabel("Median income")
        return fig

    @render.data_frame
    def grid():
        return DataGrid(filtered(), filters=True)

    @reactive.effect
    @reactive.event(input.reset)
    def _():
        ui.update_slider("min_pop", value=0)

app = App(app_ui, server)
Same five inputs and outputs as before, but it now looks like a dashboard rather than a form.

A small Shiny app showing link-level congestion
Here is a minimal dashboard using the functions above. The data is a tiny fake “network” of five corridors. Swap it for your own OSMnx-derived data when you are ready.
from shiny import App, ui, render, reactive
from shiny.render import DataGrid
import pandas as pd

# Five pretend corridors
links = pd.DataFrame({
    "corridor": ["Queen St", "Ponsonby Rd", "Great North Rd", "Broadway", "Symonds St"],
    "length_m":   [1200, 2100, 3400, 1800, 900],
    "speed_kmh":  [30, 50, 50, 50, 40],
    "capacity":   [1800, 2000, 2200, 1800, 1600],
})

def free_flow_minutes(distance_m, speed_kmh):
    return (distance_m / 1000) / speed_kmh * 60

def tti(actual, free_flow):
    return actual / free_flow if free_flow else float("nan")

def level_of_service(vc):
    for thr, letter in [(0.6, "A"), (0.7, "B"), (0.8, "C"), (0.9, "D"), (1.0, "E")]:
        if vc &lt; thr:
            return letter
    return "F"

app_ui = ui.page_sidebar(
    ui.sidebar(
        ui.input_slider("volume_pct", "Traffic volume (% of capacity)", 30, 130, 80, step=5),
        ui.input_slider("delay_pct", "Travel time inflation vs free flow (%)", 0, 150, 30, step=5),
    ),
    ui.card(
        ui.card_header("Corridor indicators"),
        ui.output_data_frame("tbl"),
    ),
    title="Auckland corridor congestion (demo)",
)

def server(input, output, session):

    @reactive.calc
    def indicators():
        df = links.copy()
        df["free_flow_min"] = free_flow_minutes(df["length_m"], df["speed_kmh"])
        df["actual_min"]    = df["free_flow_min"] * (1 + input.delay_pct() / 100)
        df["tti"]           = df["actual_min"] / df["free_flow_min"]
        df["volume"]        = df["capacity"] * input.volume_pct() / 100
        df["vc"]            = df["volume"] / df["capacity"]
        df["los"]           = df["vc"].apply(level_of_service)
        return df.round({"free_flow_min": 1, "actual_min": 1, "tti": 2, "vc": 2})

    @render.data_frame
    def tbl():
        return DataGrid(indicators(), filters=True, width="100%")

app = App(app_ui, server)
Try it: move the two sliders and watch the indicators change. Both inputs feed a single @reactive.calc; the table is the only observer. That is the pattern from 3.3, applied to a transport problem.
